var r=[{key:"edo-clasicos",nombre:"M\xE9todos de un paso",principio:"Desde un punto conocido (t\u2099, y\u2099) se estima la pendiente y se avanza un paso h hasta el punto siguiente.",descripcion:"Resuelven un problema de valor inicial y\u2032 = f(t, y), y(t\u2080) = y\u2080. Euler usa una sola pendiente y es de orden 1; RK4 combina cuatro pendientes y es de orden 4. La diferencia se ve en la calculadora: con el mismo h, RK4 comete un error much\xEDsimo menor."}],a=[{key:"euler",nombre:"Euler expl\xEDcito",ruta:"euler",familia:"edo-clasicos",idea:"Avanza en l\xEDnea recta con la pendiente del punto actual.",formula:"y\u2099\u208A\u2081 = y\u2099 + h \xB7 f(t\u2099, y\u2099)",formulaTex:"y_{n+1} = y_n + h\\,f(t_n, y_n)",criterioTexto:"Orden 1: al dividir h por 2, el error global baja a la mitad. Estable si h \u2264 2/|\u03BB|.",color:"#1b6b93"},{key:"rk4",nombre:"Runge-Kutta de orden 4 (RK4)",ruta:"rk4",familia:"edo-clasicos",idea:"Combina cuatro pendientes dentro del paso con pesos 1-2-2-1.",formula:"y\u2099\u208A\u2081 = y\u2099 + (h/6)(k\u2081 + 2k\u2082 + 2k\u2083 + k\u2084)",formulaTex:"y_{n+1} = y_n + \\frac{h}{6}\\left(k_1 + 2k_2 + 2k_3 + k_4\\right)",criterioTexto:"Orden 4: al dividir h por 2, el error global baja a la dieciseisava parte.",color:"#8a5a00"}],t=a.reduce((o,e)=>(o[e.key]=e,o),{});function n(o){return a.filter(e=>e.familia===o)}function i(o){return`/modulo5/tipos/${o}`}function l(o){return`${i(o.familia)}/${o.ruta}/teoria`}export{r as a,a as b,n as c,i as d,l as e};
